INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001170030','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001170030","revision":1,"targetId":"80000000-0000-4000-8000-000000011703","prompt":"Zwischen zehn und fünfzehn Uhr gilt bei uns die ___; in dieser Zeit müssen alle erreichbar sein.","instruction":{"en":"Choose the noun or noun form that best completes the German sentence.","de":"Wähle das Nomen oder die Nomenform, die den deutschen Satz sinnvoll ergänzt."},"hint":{"en":"A flexible schedule can still require common availability hours.","de":"Auch bei Gleitzeit kann es feste Zeiten der Erreichbarkeit geben."},"slots":[{"id":"noun","label":"Nomen oder Form","options":[{"id":"0","text":"Mittagspause"},{"id":"1","text":"Freizeit"},{"id":"2","text":"Kernarbeitszeit"},{"id":"3","text":"Urlaubszeit"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"2"}]}],"explanation":{"en":"Kernarbeitszeit is the period of mandatory availability.","de":"Kernarbeitszeit bezeichnet die verbindliche Zeit der Erreichbarkeit."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Zwischen zehn und fünfzehn Uhr gilt bei uns die Kernarbeitszeit; in dieser Zeit müssen alle erreichbar sein.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1249 (a0d9c32a2fb39eab9d0d98308e1f84f599103a81ed59d771cabdd3ba6ed535db), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
