INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001170160','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001170160","revision":1,"targetId":"80000000-0000-4000-8000-000000011716","prompt":"Milde Winter und trockene Sommer prägen das ___ dieser Küstenregion.","instruction":{"en":"Choose the noun or noun form that best completes the German sentence.","de":"Wähle das Nomen oder die Nomenform, die den deutschen Satz sinnvoll ergänzt."},"hint":{"en":"The sentence describes recurring seasonal conditions.","de":"Der Satz beschreibt typische Wetterverhältnisse über viele Jahre."},"slots":[{"id":"noun","label":"Nomen oder Form","options":[{"id":"0","text":"Gewitter"},{"id":"1","text":"Klima"},{"id":"2","text":"Gebäude"},{"id":"3","text":"Rezept"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Klima is the long-term pattern of weather in a region.","de":"Klima bezeichnet die langfristigen Wetterverhältnisse einer Region."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Milde Winter und trockene Sommer prägen das Klima dieser Küstenregion.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1275 (075577925ac4c80721530e05f3ca187dc385920980628b606fa84555e0a91ffb), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
