INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001190060','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001190060","revision":1,"targetId":"80000000-0000-4000-8000-000000011906","prompt":"Der neue Anbieter verkauft ähnliche Produkte und macht dem Unternehmen starke ___.","instruction":{"en":"Choose the noun or noun form that best completes the German sentence.","de":"Wähle das Nomen oder die Nomenform, die den deutschen Satz sinnvoll ergänzt."},"hint":{"en":"Another seller challenges the business in the same market.","de":"Ein anderer Anbieter macht dem Unternehmen den Markt streitig."},"slots":[{"id":"noun","label":"Nomen oder Form","options":[{"id":"0","text":"Kooperation"},{"id":"1","text":"Werbung"},{"id":"2","text":"Rechnung"},{"id":"3","text":"Konkurrenz"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"3"}]}],"explanation":{"en":"Konkurrenz is competitive pressure from a rival.","de":"Konkurrenz bezeichnet den Wettbewerb durch einen Rivalen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der neue Anbieter verkauft ähnliche Produkte und macht dem Unternehmen starke Konkurrenz.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1309 (4776e3f1e89e8e87873c66fa60f52ee6e35a5ef5a6cb072455343473a432f0cc), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
